using System.Text.RegularExpressions;
using Codex.ContentImport.Degrees;
using UglyToad.PdfPig;
using UglyToad.PdfPig.Content;
using UglyToad.PdfPig.Core;
using UglyToad.PdfPig.Writer;

namespace Codex.Tests;

/// <summary>The base of the local book importer. CI never sees a book: the PDF here is generated by the test.</summary>
public class DegreesImportBaseTests : IDisposable
{
    private readonly string _temp = Path.Combine(Path.GetTempPath(), "CodexDegrees_" + Guid.NewGuid());

    public DegreesImportBaseTests() => Directory.CreateDirectory(_temp);

    public void Dispose()
    {
        if (Directory.Exists(_temp)) Directory.Delete(_temp, true);
    }

    private const string TestRoles = """
        rules:
          - { role: furniture, family: [Helvetica-Bold], size: [12, 12], x: [0, 60] }
          - { role: entry-header, family: [Helvetica-Bold], size: [13, 13] }
          - { role: body, family: [Helvetica] }
        """;

    // ---- options

    [Fact]
    public void Options_ParseTheActionTheBookAndThePaths()
    {
        var run = DegreesOptions.Parse(new[] { "--book", "pc", "--pdf", "a.pdf" });
        Assert.NotNull(run);
        Assert.Equal("run", run!.Action);
        Assert.Equal("pc", run.Book);
        Assert.Equal(DegreesOptions.DefaultWork("pc"), run.Work);

        var notice = DegreesOptions.Parse(new[] { "notice", "--book", "mc", "--pdf", "b.pdf", "--work", "w" });
        Assert.Equal(("notice", "mc", "b.pdf", "w"), (notice!.Action, notice.Book, notice.Pdf, notice.Work));
    }

    [Theory]
    [InlineData("run", "--book", "pc")]
    [InlineData("run", "--pdf", "a.pdf")]
    [InlineData("run", "--book", "player-core", "--pdf", "a.pdf")]
    [InlineData("import", "--book", "pc", "--pdf", "a.pdf")]
    [InlineData("run", "--book", "pc", "--pdf", "a.pdf", "--out", "x")]
    public void Options_RejectAnythingElse(params string[] args) => Assert.Null(DegreesOptions.Parse(args));

    // ---- path guard

    [Fact]
    public void PathGuard_RefusesAPathInsideAGitWorkTree_LinksIncluded()
    {
        var tree = Directory.CreateDirectory(Path.Combine(_temp, "tree"));
        Directory.CreateDirectory(Path.Combine(tree.FullName, ".git"));
        var inside = Directory.CreateDirectory(Path.Combine(tree.FullName, "deep", "er"));
        var outside = Directory.CreateDirectory(Path.Combine(_temp, "plain"));
        var file = Path.Combine(outside.FullName, "book.pdf");
        File.WriteAllText(file, "x");

        Assert.Equal(PathGuard.Resolve(tree.FullName), PathGuard.FindGitRoot(inside.FullName));
        Assert.Throws<InvalidOperationException>(() => PathGuard.EnsureOutsideGitTree(Path.Combine(inside.FullName, "not-yet-made"), "--work"));
        Assert.Null(PathGuard.FindGitRoot(file));
        PathGuard.EnsureOutsideGitTree(file, "--pdf");

        var link = Path.Combine(outside.FullName, "link");
        Directory.CreateSymbolicLink(link, inside.FullName);
        Assert.Throws<InvalidOperationException>(() => PathGuard.EnsureOutsideGitTree(Path.Combine(link, "out"), "--work"));
    }

    [Fact]
    public void PathGuard_AWorktreeGitFileCountsToo()
    {
        var tree = Directory.CreateDirectory(Path.Combine(_temp, "worktree"));
        File.WriteAllText(Path.Combine(tree.FullName, ".git"), "gitdir: elsewhere");
        Assert.NotNull(PathGuard.FindGitRoot(Path.Combine(tree.FullName, "x")));
    }

    // ---- configuration

    [Fact]
    public void TheCommittedFingerprintsAndFontRulesLoad()
    {
        var books = BooksConfig.Embedded();
        Assert.Equal(new[] { "mc", "pc" }, books.Books.Keys.OrderBy(k => k, StringComparer.Ordinal));
        foreach (var book in books.Books.Values)
        {
            Assert.True(book.Pages > 0);
            Assert.NotEmpty(book.Bookmarks);
            Assert.NotEmpty(book.Notice);
            Assert.Contains("©", book.Credit[0]);
        }

        var roles = FontRoles.Embedded();
        Assert.Equal("rules", roles.Classify(FontRoles.Family("ABCDEF+SabonLTStd-Roman"), 9.01, 100));
        Assert.Equal("entry-header", roles.Classify("GoodOT-Bold", 13, 100));
        Assert.Equal("icon", roles.Classify("Some-Icons", 9, 100));
        Assert.Null(roles.Classify("UnknownSans", 9, 100));
    }

    [Fact]
    public void NothingTheImporterCommitsNamesAPublisherOrAGame()
    {
        // The credit line in degrees-books.yaml is the one place a product name may appear, because the licence requires it.
        var denied = new Regex("pathfinder|paizo|golarion|pf2e|remaster|starfinder|dungeons|d&d|wizards of the coast", RegexOptions.IgnoreCase);
        var files = Directory.EnumerateFiles(Path.Combine(TestPaths.RepoRoot, "tools", "Codex.ContentImport", "Degrees"), "*.cs")
            .Append(Path.Combine(TestPaths.RepoRoot, "tools", "Codex.ContentImport", "Data", "degrees-fonts.yaml"))
            .Append(Path.Combine(TestPaths.RepoRoot, "docs", "DEGREES_IMPORT_DESIGN.md"))
            .Append(Path.Combine(TestPaths.RepoRoot, "tests", "Codex.Tests", "DegreesImportBaseTests.cs"));
        var hits = files
            .SelectMany(f => File.ReadLines(f).Select((line, i) => (File: Path.GetFileName(f), Line: i + 1, Text: line)))
            .Where(l => !l.Text.Contains("orclicense", StringComparison.Ordinal) && !l.Text.Contains("denied = new Regex", StringComparison.Ordinal) && denied.IsMatch(l.Text))
            .Select(l => $"{l.File}:{l.Line}")
            .ToList();

        Assert.Empty(hits);
    }

    // ---- the notice check

    [Fact]
    public void Notice_MatchesAcrossLineAndColumnBreaks_AndNeverEchoesText()
    {
        string[] credit = { "Alpha Book © 2023 Someone, Authors: Ann Lee, Bo", "Cy Dee and Eve-Fay" };
        var page = "Alpha Book ©\n2023 Someone, Authors: Ann\nLee, Bo\n 12 Staff list • Name\nCy Dee and Eve-\nFay";
        Assert.True(NoticeCheck.Compare(page, credit).Ok);

        var wrong = NoticeCheck.Compare(page.Replace("Ann", "Ann2"), credit);
        Assert.False(wrong.Ok);
        Assert.Contains("segment 1 of 2", wrong.Message);
        Assert.DoesNotContain("Alpha", wrong.Message);
    }

    // ---- a synthetic book

    private static byte[] TwoColumnBook()
    {
        var builder = new PdfDocumentBuilder();
        var body = builder.AddStandard14Font(UglyToad.PdfPig.Fonts.Standard14Fonts.Standard14Font.Helvetica);
        var bold = builder.AddStandard14Font(UglyToad.PdfPig.Fonts.Standard14Fonts.Standard14Font.HelveticaBold);
        var page = builder.AddPage(603, 783);
        page.AddText("14", 12, new PdfPoint(30, 40), bold);
        page.AddText("Header", 13, new PdfPoint(60, 700), bold);
        for (var i = 0; i < 8; i++)
        {
            page.AddText($"left col line {i}", 9, new PdfPoint(60, 680 - i * 11), body);
            page.AddText($"right col line {i}", 9, new PdfPoint(320, 700 - i * 11), body);
        }

        return builder.Build();
    }

    [Fact]
    public void Layout_GivesEveryLetterARole_AndTheBlocksSplitIntoColumnsWithoutFurniture()
    {
        using var doc = PdfDocument.Open(TwoColumnBook());
        var layout = LayoutStage.Run(doc, FontRoles.Parse(TestRoles));

        Assert.Empty(layout.Unclassified);
        Assert.Equal(new[] { "body", "entry-header", "furniture" }, layout.LettersByRole.Keys.OrderBy(k => k, StringComparer.Ordinal));

        var blocks = BlocksStage.Run(layout.Pages);
        Assert.Equal(1, blocks.TwoColumnPages);
        Assert.Equal(1, blocks.FurnitureWords);
        Assert.Equal(new[] { (0, "entry-header", 1), (0, "body", 8), (1, "body", 8) }, blocks.Blocks.Select(b => (b.Column, b.Role, b.Lines.Count)).OrderBy(b => b.Column).ThenByDescending(b => b.Role == "entry-header").ToArray());
        Assert.DoesNotContain(blocks.Blocks, b => b.Lines.Any(l => l.Contains("14")));
    }

    [Fact]
    public void Layout_ReportsAFontWithNoRoleByCountAndPageOnly()
    {
        var builder = new PdfDocumentBuilder();
        var body = builder.AddStandard14Font(UglyToad.PdfPig.Fonts.Standard14Fonts.Standard14Font.Helvetica);
        var other = builder.AddStandard14Font(UglyToad.PdfPig.Fonts.Standard14Fonts.Standard14Font.TimesRoman);
        var page = builder.AddPage(603, 783);
        page.AddText("known", 9, new PdfPoint(60, 700), body);
        page.AddText("stray", 9, new PdfPoint(60, 600), other);

        using var doc = PdfDocument.Open(builder.Build());
        var layout = LayoutStage.Run(doc, FontRoles.Parse(TestRoles));

        var stray = Assert.Single(layout.Unclassified);
        Assert.Equal(5, stray.Letters);
        Assert.Equal(new[] { 1 }, stray.FirstPages);
        Assert.Contains(layout.Pages[0].Words, w => w.Role == "unclassified");
    }

    [Fact]
    public void TheCommandRefusesAPdfInsideAGitWorkTree_AndWritesNothing()
    {
        var tree = Directory.CreateDirectory(Path.Combine(_temp, "repo"));
        Directory.CreateDirectory(Path.Combine(tree.FullName, ".git"));
        var pdf = Path.Combine(tree.FullName, "book.pdf");
        File.WriteAllBytes(pdf, TwoColumnBook());
        var work = Path.Combine(_temp, "work");

        using var error = new StringWriter();
        var code = DegreesCommand.Run(new[] { "--book", "pc", "--pdf", pdf, "--work", work }, new StringWriter(), error);

        Assert.Equal(1, code);
        Assert.Contains("outside any git work tree", error.ToString());
        Assert.False(Directory.Exists(work));
    }

    [Fact]
    public void TheCommandStopsOnADifferentPrinting_BeforeWritingAnything()
    {
        var pdf = Path.Combine(_temp, "book.pdf");
        File.WriteAllBytes(pdf, TwoColumnBook());
        var work = Path.Combine(_temp, "work");

        using var error = new StringWriter();
        var code = DegreesCommand.Run(new[] { "--book", "pc", "--pdf", pdf, "--work", work }, new StringWriter(), error);

        Assert.Equal(1, code);
        Assert.Contains("different printing; re-review every chapter", error.ToString());
        Assert.False(Directory.Exists(work));
    }
}
